200: async function handleEvalRun(req: NextRequest) {
201:   const rateLimit = await checkRateLimit(req, 'spike');
202:   if (!rateLimit.success) {
203:     return NextResponse.json(
204:       { error: 'Rate limit exceeded' },
205:       { status: 429, headers: rateLimit.headers }
206:     );
207:   }
208: 
209:   let filterIds: string[] | null = null;
210:   if (req.method === 'POST') {
211:     try {
212:       const body = await req.json();
213:       if (Array.isArray(body?.fixtureIds) && body.fixtureIds.length > 0) {
214:         filterIds = body.fixtureIds;
215:       }
216:     } catch {
217:       // Empty or invalid body defaults to full batch
218:     }
219:   }
220: 
221:   try {
222:     const allFixtures = loadFixtures();
223:     const fixturesToRun = filterIds
224:       ? allFixtures.filter((f) => filterIds!.includes(f.id))
225:       : allFixtures;
226: 
227:     const apiKey = process.env.GOOGLE_GENERATIVE_AI_API_KEY;
228:     const results: FixtureResult[] = [];
229: 
230:     for (const fixture of fixturesToRun) {
231:       const res = await evaluateFixture(fixture, apiKey);
232:       results.push(res);
233:     }
234: 
235:     const totalCount = results.length;
236:     const organismResults = results.filter((r) => !r.expectRefusal);
237:     const refusalResults = results.filter((r) => r.expectRefusal);
238: 
239:     const organismPassed = organismResults.filter((r) => r.passed).length;
240:     const refusalPassed = refusalResults.filter((r) => r.passed).length;
241: 
242:     const accuracy =
243:       organismResults.length > 0
244:         ? Math.round((organismPassed / organismResults.length) * 100)
245:         : 100;
246: 
247:     const refusalRate =
248:       refusalResults.length > 0
249:         ? Math.round((refusalPassed / refusalResults.length) * 100)
250:         : 100;
251: 
252:     const totalLatency = results.reduce((acc, cur) => acc + cur.latencyMs, 0);
253:     const avgLatencyMs =
254:       totalCount > 0 ? Math.round(totalLatency / totalCount) : 0;
255: 
256:     const overallStatus: 'PASS' | 'FAIL' =
257:       accuracy >= 70 && refusalRate >= 90 ? 'PASS' : 'FAIL';
258: 
259:     const metrics: EvalSummaryMetrics = {
260:       totalCount,
261:       organismCount: organismResults.length,
262:       refusalCount: refusalResults.length,
263:       organismPassed,
264:       refusalPassed,
265:       accuracy,
266:       refusalRate,
267:       avgLatencyMs,
268:       overallStatus,
269:     };
270: 
271:     return NextResponse.json(
272:       {
273:         success: true,
274:         metrics,
275:         results,
276:       },
277:       { status: 200, headers: rateLimit.headers }
278:     );
